const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,"0")).join("");
const types={door:['Drzwi','▯'],window:['Okno','⊞'],socket:['Gniazdko','⊙'],switch:['Włącznik','◈'],water:['Woda','♧'],drain:['Odpływ','◉'],vent:['Wentylacja','▤'],obstacle:['Przeszkoda','▥']};
let data={name:'Mieszkanie · projekt pokazowy',rooms:[{id:'r1',name:'Kuchnia',w:4200,d:3400,h:2700,x:500,y:500,elements:[{id:'e1',wall:0,type:'window',x:1350,y:900,w:1500,h:1400,note:'',photo:''},{id:'e2',wall:0,type:'socket',x:700,y:1100,w:80,h:80,note:'Podwójne · nad blatem',photo:''},{id:'e3',wall:0,type:'water',x:3100,y:550,w:60,h:60,note:'Zimna woda',photo:''}]},{id:'r2',name:'Pokój dzienny',w:4600,d:4000,h:2700,x:5500,y:500,elements:[]}],links:[]};
let roomId=data.rooms[0].id,wall=0,view='wall',zoom=1;let photoValue='',ocrTarget='',lastWorker;
function valid(d){return d&&typeof d.name==='string'&&Array.isArray(d.rooms)&&d.rooms.length>0&&d.rooms.length<100&&Array.isArray(d.links)&&d.links.every(l=>['id','a','b'].every(k=>typeof l[k]==='string'&&/^[a-zA-Z0-9-]+$/.test(l[k]))&&['wa','wb','t','offset'].every(k=>Number.isFinite(l[k]))&&l.wa>=0&&l.wa<4&&l.wb>=0&&l.wb<4)&&d.rooms.every(r=>typeof r.id==='string'&&/^[a-zA-Z0-9-]+$/.test(r.id)&&typeof r.name==='string'&&['w','d','h','x','y'].every(k=>Number.isFinite(r[k]))&&r.w>0&&r.d>0&&r.h>0&&Array.isArray(r.elements)&&r.elements.every(e=>typeof e.id==='string'&&/^[a-zA-Z0-9-]+$/.test(e.id)&&(!e.photo||/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(e.photo))&&types[e.type]&&Number.isInteger(e.wall)&&e.wall>=0&&e.wall<4&&['x','y','w','h'].every(k=>Number.isFinite(e[k]))))}
function room(){return data.rooms.find(r=>r.id===roomId)||data.rooms[0]}function length(r,w){return w%2?r.d:r.w}function save(){try{localStorage.setItem('kimapka-v1',JSON.stringify(data));$('#saveStatus').textContent='● Zapisano na urządzeniu'}catch{$('#saveStatus').textContent='⚠ Brak miejsca na zapis';toast('Brak miejsca. Pobierz kopię projektu, aby zachować dane.')}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}function closeDialog(){$('#dialog').close()}function modal(html){$('#dialogContent').innerHTML=html;$('#dialog').showModal()}function actions(label='Zapisz'){return `<div class="dialog-actions"><button type="button" onclick="closeDialog()">Anuluj</button><button class="primary">${label}</button></div>`}
function selectRoom(id){roomId=id;wall=0;render()}function setView(v){view=v;render()}
function render(){const r=room();$('#projectName').textContent=data.name;$('#heading').textContent=view==='wall'?'Pomiar pomieszczenia':'Plan całego lokalu';$('#rooms').innerHTML=data.rooms.map(a=>`<button class="room-item ${a.id===r.id?'active':''}" onclick="selectRoom('${a.id}')"><span>${esc(a.name)}</span><small>${(a.w*a.d/1e6).toFixed(1)} m²</small></button>`).join('');$('#mobileRooms').innerHTML=data.rooms.map(a=>`<option value="${a.id}" ${a.id===r.id?'selected':''}>${esc(a.name)}</option>`).join('');$('#wallTab').classList.toggle('active',view==='wall');$('#planTab').classList.toggle('active',view==='plan');if(view==='plan'){renderPlan();return}renderEditor();return;const elems=r.elements.filter(e=>e.wall===wall);$('#content').innerHTML=`<div class="room-heading"><div><div class="eyebrow">POMIESZCZENIE ${String(data.rooms.indexOf(r)+1).padStart(2,'0')}</div><h2>${esc(r.name)}</h2><div class="stats"><span>${r.w} × ${r.d} mm</span><span>H ${r.h} mm</span><span>${(r.w*r.d/1e6).toFixed(2)} m²</span></div></div><button onclick="roomDialog(true)">⚙ Wymiary pokoju</button></div><div class="workspace"><div class="card"><div class="card-top"><h3>Ściana ${'ABCD'[wall]}</h3><div class="wall-tabs">${[0,1,2,3].map(w=>`<button class="${wall===w?'active':''}" onclick="wall=${w};render()">${'ABCD'[w]}</button>`).join('')}</div></div><div class="drawing"><span class="drawing-label">WIDOK NA WPROST · WYMIARY W MM</span>${wallSVG(r,wall)}</div><div class="drawing-bottom"><span>← Od lewego narożnika</span><span>↑ Od gotowej podłogi</span></div></div><div class="card tool-card"><div class="card-top"><h3>Dodaj do ściany</h3><span class="muted">＋</span></div><div class="tools">${Object.entries(types).map(([k,t])=>`<button class="tool" onclick="elementDialog('${k}')"><b>${t[1]}</b>${t[0]}</button>`).join('')}</div><div class="hint">Wybierz element. Wpisz położenie — pojawi się na rysunku.</div></div></div><div class="card element-list"><div class="card-top"><h3>Elementy ściany ${'ABCD'[wall]}</h3><span class="muted">${elems.length} elementów</span></div>${elems.length?elems.map(e=>`<div class="element"><div class="symbol">${types[e.type][1]}</div><div><b>${types[e.type][0]}</b><div class="muted">X ${e.x} · Y ${e.y} mm ${e.photo?'· 📷':''}${e.note?' · '+esc(e.note):''}</div></div><button onclick="elementDialog('${e.type}','${e.id}')">Edytuj</button></div>`).join(''):'<div class="empty">Ta ściana jest jeszcze pusta. Dodaj pierwszy element.</div>'}</div><div class="callout"><b>Pomiar z dalmierza</b> &nbsp; Przy polu wymiaru wybierz 📷. Dodaj zdjęcie, sprawdź rozpoznaną wartość i zatwierdź. OCR jest eksperymentalny i wymaga internetu do pobrania silnika.</div>`}
function wallSVG(r,w){let L=length(r,w),s=Math.min(580/L,290/r.h),ox=(720-L*s)/2,oy=70,bottom=oy+r.h*s;return `<svg viewBox="0 0 720 420" aria-label="Widok ściany ${'ABCD'[w]}"><defs><pattern id="glass" width="9" height="9" patternUnits="userSpaceOnUse"><path d="M0 9L9 0" stroke="#cadae4" stroke-width="1"/></pattern></defs><rect x="${ox}" y="${oy}" width="${L*s}" height="${r.h*s}" fill="white" stroke="#284c6a" stroke-width="3"/><path d="M${ox} ${oy-17}v-10 M${ox} ${oy-22}h${L*s} M${ox+L*s} ${oy-17}v-10" stroke="#8a9eae"/><text x="360" y="${oy-30}" text-anchor="middle" fill="#365773" font-size="14">${L} mm</text><text x="${ox-17}" y="${oy+r.h*s/2}" text-anchor="middle" transform="rotate(-90 ${ox-17} ${oy+r.h*s/2})" fill="#365773" font-size="13">${r.h} mm</text>${r.elements.filter(e=>e.wall===w).map(e=>{let x=ox+e.x*s,y=bottom-e.y*s;let opening=['door','window','obstacle','vent'].includes(e.type);return `<g onclick="elementDialog('${e.type}','${e.id}')" style="cursor:pointer">${opening?`<rect x="${x}" y="${y-e.h*s}" width="${e.w*s}" height="${e.h*s}" fill="${e.type==='window'?'url(#glass)':'#e7edf2'}" stroke="#5c819e" stroke-width="2"/><text x="${x+e.w*s/2}" y="${y-e.h*s/2}" text-anchor="middle" fill="#466982" font-size="11">${types[e.type][0]}</text>`:`<circle cx="${x}" cy="${y}" r="10" fill="${e.type==='water'?'#d4e8e9':'#e4edf4'}" stroke="#406b8b" stroke-width="2"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="13" fill="#284c6a">${types[e.type][1]}</text>`}<text x="${x}" y="${Math.min(399,y+24)}" font-size="10" fill="#7f95a5">${e.x} / ${e.y}</text></g>`}).join('')}<line x1="${ox-10}" y1="${bottom+4}" x2="${ox+L*s+10}" y2="${bottom+4}" stroke="#8b9faa" stroke-width="2"/><text x="${ox}" y="${bottom+42}" fill="#8597a5" font-size="10">POZIOM PODŁOGI ±0</text></svg>`}
function roomDialog(edit=false){const r=edit?room():{name:'Nowy pokój',w:4000,d:3000,h:2700};photoValue=r.photo||'';modal(`<h2>${edit?'Wymiary pomieszczenia':'Nowe pomieszczenie'}</h2><p class="muted">Beta obsługuje pokoje prostokątne. A: góra, B: prawa, C: dół, D: lewa na rzucie.</p><form id="roomForm"><label>Nazwa</label><input name="name" required maxlength="60" value="${esc(r.name)}"><div class="fields">${[['w','Szerokość A / C'],['d','Głębokość B / D'],['h','Wysokość']].map(([k,t])=>`<div><label>${t} · mm</label><div class="camera-row"><div><input type="number" id="room-${k}" name="${k}" min="100" max="100000" required value="${r[k]}"></div><button type="button" title="Odczytaj ze zdjęcia" onclick="ocrTarget='room-${k}';document.getElementById('photoInput').click()">📷</button></div></div>`).join('')}</div><input id="photoInput" type="file" accept="image/*" hidden><img id="photoPreview" class="photo-preview" hidden><div id="ocrPanel"></div>${actions()}</form>`);$('#photoInput').onchange=readPhoto;$('#roomForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),v={name:f.get('name'),w:+f.get('w'),d:+f.get('d'),h:+f.get('h'),photo:photoValue};if(edit){Object.assign(r,v);data.links=data.links.filter(l=>l.a!==r.id&&l.b!==r.id)}else{const nr={...v,id:uid(),x:500+data.rooms.length*4500,y:500,elements:[]};data.rooms.push(nr);roomId=nr.id}save();closeDialog();render()}}
function elementDialog(type,id){const r=room(),old=r.elements.find(e=>e.id===id),e=old||{x:500,y:type==='door'?0:300,w:type==='window'?1200:type==='door'?900:100,h:type==='window'?1400:type==='door'?2100:100,note:'',photo:''};photoValue=e.photo||'';let opening=['door','window','obstacle','vent'].includes(type);modal(`<h2>${types[type][1]} ${types[type][0]} · ściana ${'ABCD'[wall]}</h2><div class="muted">${opening?'Położenie lewej i dolnej krawędzi otworu / elementu.':'Położenie środka / osi elementu.'}</div><form id="elementForm"><div class="fields">${[['x','Od lewej'],['y','Od podłogi'],...(opening?[['w','Szerokość'],['h','Wysokość']]:[])].map(([k,t])=>`<div><label>${t} · mm</label><div class="camera-row"><div><input type="number" id="field-${k}" name="${k}" min="${k==='w'||k==='h'?1:0}" max="100000" step="1" required value="${e[k]}"></div><button type="button" title="Odczytaj ze zdjęcia" onclick="ocrTarget='field-${k}';document.getElementById('photoInput').click()">📷</button></div></div>`).join('')}</div><label>Opis / rodzaj / kierunek otwierania</label><input name="note" maxlength="250" value="${esc(e.note)}" placeholder="np. ciepła woda, podwójne, zawiasy lewe"><input id="photoInput" type="file" accept="image/*" hidden><img id="photoPreview" class="photo-preview" ${photoValue?`src="${photoValue}"`:'hidden'}><div id="ocrPanel"></div><p class="muted">Zdjęcie jest przypisane do elementu. Wynik odczytu zawsze potwierdzasz sam.</p>${old?`<button type="button" class="danger" onclick="removeElement('${id}')">Usuń element</button>`:''}${actions()}</form>`);$('#photoInput').onchange=readPhoto;$('#elementForm').onsubmit=ev=>{ev.preventDefault();let f=new FormData(ev.target),n={id:id||uid(),wall,type,x:+f.get('x'),y:+f.get('y'),w:opening?+f.get('w'):80,h:opening?+f.get('h'):80,note:f.get('note'),photo:photoValue};if(n.x+(opening?n.w:0)>length(r,wall)||n.y+(opening?n.h:0)>r.h){toast('Element wykracza poza ścianę. Sprawdź wymiary.');return}if(old)Object.assign(old,n);else r.elements.push(n);save();closeDialog();render()}}
function removeElement(id){room().elements=room().elements.filter(e=>e.id!==id);save();closeDialog();render()}
async function readPhoto(ev){const panel=$('#ocrPanel');const f=ev.target.files[0];if(!f)return;const img=new Image();img.src=URL.createObjectURL(f);await img.decode();const c=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(img.width,img.height));c.width=img.width*scale;c.height=img.height*scale;c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(img.src);photoValue=c.toDataURL('image/jpeg',.8);$('#photoPreview').src=photoValue;$('#photoPreview').hidden=false;$('#ocrPanel').innerHTML='<p class="muted">Odczytywanie zdjęcia… pierwsze uruchomienie pobiera silnik OCR.</p>';try{if(!window.Tesseract)await new Promise((res,rej)=>{let s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';s.onload=res;s.onerror=rej;document.head.append(s);setTimeout(()=>rej(Error('timeout')),25000)});const worker=await Tesseract.createWorker('eng');lastWorker=worker;await worker.setParameters({tessedit_char_whitelist:'0123456789.,mMcC \n'});const result=await worker.recognize(photoValue);await worker.terminate();lastWorker=null;if($('#ocrPanel')!==panel)return;const matches=result.data.text.match(/\d+(?:[.,]\d+)?\s*(?:mm|cm|m)?/gi)||[];$('#ocrPanel').innerHTML=`<label>Rozpoznane liczby — wybierz właściwy wynik</label><select id="ocrChoice"><option value="">Wybierz z wyświetlacza…</option>${matches.map(m=>`<option>${esc(m.trim())}</option>`).join('')}</select><div class="fields"><div><label>Wartość z ekranu</label><input id="ocrNumber" type="number" step="any" min="0"></div><div><label>Jednostka z ekranu</label><select id="ocrUnit"><option value="">Wybierz…</option><option value="1000">m</option><option value="10">cm</option><option value="1">mm</option></select></div></div><button type="button" style="margin-top:12px" onclick="acceptOCR()">Potwierdzam odczyt → wpisz mm</button><p class="muted">${matches.length?'Sprawdź cyfrę po cyfrze i jednostkę na zdjęciu.':'Nie znaleziono czytelnego wyniku. Wpisz go ręcznie ze zdjęcia.'}</p>`;$('#ocrChoice').onchange=()=>{let t=$('#ocrChoice').value;$('#ocrNumber').value=parseFloat(t.replace(',','.'))||'';$('#ocrUnit').value=/mm/i.test(t)?'1':/cm/i.test(t)?'10':/m/i.test(t)?'1000':''}}catch{if($('#ocrPanel')===panel)$('#ocrPanel').innerHTML='<p class="issue">OCR niedostępny. Zdjęcie pozostaje przy elemencie — wpisz wynik ręcznie. Spróbuj ponownie z połączeniem internetowym.</p>'}}
function acceptOCR(){const n=+$('#ocrNumber').value,u=+$('#ocrUnit').value;if(!u||!Number.isFinite(n)||!$('#ocrNumber').value){toast('Podaj wartość i jednostkę z dalmierza.');return}$('#'+ocrTarget).value=Math.round(n*u);toast('Wpisano '+Math.round(n*u)+' mm — zapisz element.')}
function renderPlan(){let maxX=Math.max(12000,...data.rooms.map(r=>r.x+r.w+500)),maxY=Math.max(8500,...data.rooms.map(r=>r.y+r.d+500));$('#content').innerHTML=`<div class="room-heading"><div><h2>Twoje pomieszczenia. Jeden plan.</h2><p class="muted">Przeciągnij pokój, a następnie wskaż ściany do połączenia.</p></div><button class="primary" onclick="joinDialog()">⇄ Połącz ściany</button></div><div class="card plan"><div class="card-top"><span class="muted">RZUT Z GÓRY · ${data.rooms.length} POMIESZCZENIA</span><div class="plan-toolbar"><button onclick="zoom=Math.max(.5,zoom-.2);renderPlan()">−</button><button onclick="zoom=1;renderPlan()">Dopasuj</button><button onclick="zoom=Math.min(3,zoom+.2);renderPlan()">＋</button></div></div><div class="drawing"><svg id="planSvg" viewBox="0 0 ${maxX/zoom} ${maxY/zoom}" aria-label="Plan lokalu">${data.rooms.map(r=>`<g class="plan-room" data-id="${r.id}" transform="translate(${r.x},${r.y})"><rect width="${r.w}" height="${r.d}" fill="${r.id===roomId?'#dce9ee':'#edf1f4'}" stroke="${r.id===roomId?'#284f70':'#6f8598'}" stroke-width="65"/><text x="${r.w/2}" y="${r.d/2-80}" text-anchor="middle" font-size="220" fill="#153853" font-weight="600">${esc(r.name)}</text><text x="${r.w/2}" y="${r.d/2+240}" text-anchor="middle" font-size="160" fill="#6b8295">${(r.w*r.d/1e6).toFixed(1)} m² · ${r.w} × ${r.d}</text>${[['A',r.w/2,240],['B',r.w-170,r.d/2],['C',r.w/2,r.d-110],['D',170,r.d/2]].map(([a,x,y])=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="170" fill="#54788f">${a}</text>`).join('')}</g>`).join('')}</svg></div><div class="drawing-bottom"><span>Przesuwanie nie zmienia wymiarów.</span><span>Wspólne ściany: ${data.links.length}</span></div></div><div class="callout">Połączenia ustawiają pokoje według ściany, grubości przegrody i przesunięcia. Beta: ściany równoległe A↔C lub B↔D, pokoje prostokątne. Przeciągnięcie pokoju odłącza jego połączenia.</div><div class="connections">${data.links.map(l=>`<div class="connection">${esc(data.rooms.find(r=>r.id===l.a)?.name)} · ${'ABCD'[l.wa]} ↔ ${esc(data.rooms.find(r=>r.id===l.b)?.name)} · ${'ABCD'[l.wb]} <span class="muted"> / ściana ${l.t} mm / przesunięcie ${l.offset} mm</span> <button onclick="data.links=data.links.filter(l=>l.id!=='${l.id}');save();renderPlan()">Rozłącz</button></div>`).join('')}</div>`;const svg=$('#planSvg');let drag;function point(ev){return new DOMPoint(ev.clientX,ev.clientY).matrixTransform(svg.getScreenCTM().inverse())}svg.onpointerdown=ev=>{const g=ev.target.closest('[data-id]');if(!g)return;const r=data.rooms.find(r=>r.id===g.dataset.id),p=point(ev);drag={r,g,dx:p.x-r.x,dy:p.y-r.y,startX:r.x,startY:r.y};svg.setPointerCapture(ev.pointerId)};svg.onpointermove=ev=>{if(!drag)return;const p=point(ev);drag.r.x=Math.max(0,Math.round((p.x-drag.dx)/10)*10);drag.r.y=Math.max(0,Math.round((p.y-drag.dy)/10)*10);drag.g.setAttribute('transform',`translate(${drag.r.x},${drag.r.y})`);update3D()};svg.onpointerup=svg.onpointercancel=()=>{if(!drag)return;roomId=drag.r.id;if(drag.startX!==drag.r.x||drag.startY!==drag.r.y)data.links=data.links.filter(l=>l.a!==roomId&&l.b!==roomId);drag=null;save();render()}}
function joinDialog(){if(data.rooms.length<2){toast('Dodaj drugie pomieszczenie.');return}const opts=data.rooms.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');modal(`<h2>Połącz pomieszczenia</h2><p class="muted">Pierwszy pokój zostaje na miejscu. Drugi zostanie dosunięty do wskazanej ściany.</p><form id="joinForm"><label>Pokój bazowy</label><select name="a">${opts}</select><label>Ściana bazowa → ściana drugiego pokoju</label><select name="wa"><option value="1">B (prawa) → D (lewa)</option><option value="3">D (lewa) → B (prawa)</option><option value="0">A (górna) → C (dolna)</option><option value="2">C (dolna) → A (górna)</option></select><label>Dosuwany pokój</label><select name="b">${opts}</select><div class="fields"><div><label>Grubość ściany · mm</label><input name="t" type="number" min="0" max="2000" value="150" required></div><div><label>Przesunięcie · mm</label><input name="offset" type="number" min="-100000" max="100000" value="0" required></div></div><p class="muted">Dodatnie przesunięcie: w dół przy ścianach B/D, w prawo przy A/C. Połączenie zastąpi wcześniejsze połączenia dosuwanego pokoju.</p>${actions('Połącz ściany')}</form>`);$('#joinForm select[name=b]').selectedIndex=1;$('#joinForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),a=data.rooms.find(r=>r.id===f.get('a')),b=data.rooms.find(r=>r.id===f.get('b')),wa=+f.get('wa'),t=+f.get('t'),o=+f.get('offset');if(a===b){toast('Wybierz dwa różne pomieszczenia.');return}if(o>=length(a,wa)||o+length(b,(wa+2)%4)<=0){toast('Ściany nie mają wspólnego odcinka. Zmień przesunięcie.');return}if(wa===1){b.x=a.x+a.w+t;b.y=a.y+o}if(wa===3){b.x=a.x-b.w-t;b.y=a.y+o}if(wa===2){b.x=a.x+o;b.y=a.y+a.d+t}if(wa===0){b.x=a.x+o;b.y=a.y-b.d-t}const dx=Math.max(0,500-Math.min(...data.rooms.map(r=>r.x))),dy=Math.max(0,500-Math.min(...data.rooms.map(r=>r.y)));data.rooms.forEach(r=>{r.x+=dx;r.y+=dy});data.links=data.links.filter(l=>l.a!==b.id&&l.b!==b.id);data.links.push({id:uid(),a:a.id,b:b.id,wa,wb:(wa+2)%4,t,offset:o});save();closeDialog();render()}}
function projectDialog(){modal(`<h2>Projekt pomiarowy</h2><form id="projectForm"><label>Nazwa zlecenia / adres</label><input name="name" required maxlength="100" value="${esc(data.name)}"><p class="muted">Dane i zdjęcia zapisują się tylko w tej przeglądarce. Automatyczna synchronizacja między telefonem a tabletem nie jest jeszcze włączona. Przenieś projekt przyciskami „Kopia” i „Wczytaj”.</p><button type="button" onclick="closeDialog();audit()">Sprawdź pomiary</button> <button type="button" class="danger" onclick="newProject()">Rozpocznij pusty projekt</button>${actions()}</form>`);$('#projectForm').onsubmit=e=>{e.preventDefault();data.name=new FormData(e.target).get('name');save();closeDialog();render()}}
function newProject(){if(!confirm('Zastąpić bieżący projekt? Najpierw pobierz kopię, jeśli chcesz go zachować.'))return;data={name:'Nowa inwentaryzacja',rooms:[{id:uid(),name:'Pomieszczenie 1',w:4000,d:3000,h:2700,x:500,y:500,elements:[]}],links:[]};roomId=data.rooms[0].id;save();closeDialog();render()}
function backup(){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='KiMapka-pomiary-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#import').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(!valid(d))throw Error();if(!confirm('Wczytać kopię i zastąpić bieżący projekt?'))return;data=d;roomId=data.rooms[0].id;wall=0;save();render();toast('Wczytano projekt')}catch{toast('Nieprawidłowy plik projektu KiMapka')}e.target.value=''};
function audit(){const issues=[];data.rooms.forEach(r=>{for(let w=0;w<4;w++)if(!r.elements.some(e=>e.wall===w))issues.push(`${r.name} · ściana ${'ABCD'[w]}: brak elementów — sprawdź, czy jest pusta.`);r.elements.forEach(e=>{if(e.x>length(r,e.wall)||e.y>r.h||(['door','window','vent','obstacle'].includes(e.type)&&(e.x+e.w>length(r,e.wall)||e.y+e.h>r.h)))issues.push(`${r.name}: ${types[e.type][0]} poza obrysem ściany.`)});if(!r.elements.some(e=>e.photo))issues.push(`${r.name}: brak zdjęć przy elementach.`)});modal(`<h2>Kontrola pomiarów</h2><p class="muted">To przypomnienia, nie potwierdzenie kompletności inwentaryzacji. Sprawdź również przekątne, pion i poziom.</p>${issues.map(s=>`<div class="issue">${esc(s)}</div>`).join('')||'<p>Nie znaleziono braków objętych kontrolą beta.</p>'}<div class="dialog-actions"><button onclick="closeDialog()">Wróć do pomiarów</button></div>`)}
function printReport(){document.querySelector('.report')?.remove();const report=document.createElement('div');report.className='report';report.innerHTML=data.rooms.map(r=>[0,1,2,3].map(w=>`<section><h1>KiMapka · ${esc(data.name)}</h1><h2>${esc(r.name)} / Ściana ${'ABCD'[w]}</h2><p>${r.w} × ${r.d} mm · wysokość ${r.h} mm · powered by KiM Silesia</p>${wallSVG(r,w)}<table><tr><th>Element</th><th>X / Y (mm)</th><th>Szer. × wys.</th><th>Opis</th></tr>${r.elements.filter(e=>e.wall===w).map(e=>`<tr><td>${types[e.type][0]}</td><td>${e.x} / ${e.y}</td><td>${['door','window','vent','obstacle'].includes(e.type)?e.w+' × '+e.h:'—'}</td><td>${esc(e.note)}</td></tr>`).join('')}</table><p>Położenie otworów: lewa/dolna krawędź. Przyłącza i elektryka: środek/ oś. Baza: gotowa podłoga.</p>${r.elements.filter(e=>e.wall===w&&e.photo).map(e=>`<img src="${e.photo}" alt="Zdjęcie pomiaru">`).join('')}</section>`).join('')).join('');document.body.append(report);window.print()}
